import firebase_admin
from firebase_admin import credentials, auth, firestore
from datetime import datetime, timedelta

# 1. Initialize admin privileges
cred = credentials.Certificate("service_key.json")
firebase_admin.initialize_app(cred)
db = firestore.client()

print("🔒 Admin SDK connected.\n")

def clear_collections():
    print("🧹 Clearing existing sessions, attendance, and QR history for a clean slate...")
    # These are the collections generated by the tracking system
    collections = ['sessions', 'attendance', 'qr_codes', 'attendance_pings']
    for coll in collections:
        # Use a batch delete for efficiency
        docs = db.collection(coll).stream()
        count = 0
        batch = db.batch()
        for doc in docs:
            batch.delete(doc.reference)
            count += 1
            if count % 500 == 0:
                batch.commit()
                batch = db.batch()
        batch.commit()
        if count > 0:
            print(f"   - Deleted {count} documents from '{coll}'")
    print("✨ Cloud is now clean.\n")

