# =========================================================================
# 2. RAPID TEST SESSION GENERATION (5m Class / 5m Buffer)
# =========================================================================
sessions_data = {}

# Timeframe: 04/07/2026 17:55 to 05/07/2026 23:55
current_dt = datetime(2026, 7, 6, 2, 5, 0)
end_dt = datetime(2026, 7, 7, 23, 55, 0)

print(f"📅 Generating Rapid Test sessions for Jeremy (SWE304)...")
print(f"   Mode: 5-minute sessions with 5-minute buffers.")

while current_dt <= end_dt:
    # Class Window: 5 minutes
    start_time = current_dt
    end_time = current_dt + timedelta(minutes=5)

    session_id = f"rapid_{start_time.strftime('%Y%m%d_%H%M')}"

    sessions_data[session_id] = {
        "class_id": 3, # Computer Graphics (SWE304)
        "session_date": start_time.strftime('%Y-%m-%d'),
        "start_time": start_time.strftime('%H:%M:%S'),
        "end_time": end_time.strftime('%H:%M:%S'),
        "room_number": "Rapid Lab"
    }

    # Move to next session: 5m class + 5m buffer = 10 minutes total jump
    current_dt += timedelta(minutes=10)

# =========================================================================
# 3. EXECUTION WORKFLOW
# =========================================================================

def seed_master():
    clear_collections()
    print(f"--- STARTING RAPID SEED (Generating {len(sessions_data)} sessions) ---")

    # Ensure users exist (Upsert)
    for uid, u in users_data.items():
        profile = {
            "user_id": u["user_id"], "university_id": u["university_id"],
            "name": u["name"], "role": u["role"],
            "department_ids": user_departments_links.get(uid, []),
            "last_updated": firestore.SERVER_TIMESTAMP
        }
        db.collection("users").document(uid).set(profile, merge=True)

    # Rebuild Classes
    for cid, payload in classes_data.items():
        payload["enrolled_student_ids"] = enrollments_map.get(cid, [])
        db.collection("classes").document(cid).set({**payload, "last_updated": firestore.SERVER_TIMESTAMP})

    # Add the high-frequency sessions
    batch = db.batch()
    count = 0
    for sid, payload in sessions_data.items():
        batch.set(db.collection("sessions").document(sid), payload)
        count += 1
        if count % 500 == 0:
            batch.commit()
            batch = db.batch()
    batch.commit()

    print(f"\n🎯 RAPID TEST READY! {len(sessions_data)} sessions created for Dr. Jeremy.")
    print("👉 Every session is 5 mins ON, 5 mins OFF.")

if __name__ == "__main__":
    seed_master()
